SELECT AVG(p.stoptime - p.starttime) AS average_duration FROM prescriptions p JOIN patients pt ON p.subject_id = pt.subject_id JOIN admissions a ON p.hadm_id = a.hadm_id WHERE pt.gender = 'M' AND pt.anchor_age = 69 AND a.admittime BETWEEN '2015-01-01' AND '2025-12-31' AND (p.drug ilike '%spironolactone%' OR p.drug ilike '%eplerenone%') AND EXTRACT(YEAR FROM a.admittime) BETWEEN 2015 AND 2025 AND (pt.anchor_year BETWEEN 64 AND 74 OR pt.anchor_year_group = '64-74');